        def on_enter(widget, event, data):
            callback(widget.v_model)

        widget = cast(ipyvue.VueWidget, solara.get_widget(el))
        widget.on_event("keyup.enter", on_enter)

        def cleanup():
            widget.on_event("keyup.enter", on_enter, remove=True)

        return cleanup

